const htmlBody = $input.all()[0].json.html || '';
if (!htmlBody) throw new Error('No HTML body found in email.');

const hrefPattern = /href="(https:\/\/kyotogakuen1-my\.sharepoint\.com[^"]+)"/gi;
const links = [];
let match;
while ((match = hrefPattern.exec(htmlBody)) !== null) {
  links.push({ url: match[1], index: match.index });
}

if (links.length === 0) {
  throw new Error('No SharePoint links found.');
}

// Check surrounding context around each link to identify the Halal menu.
// Prefer English keyword ("Halal") over Japanese ("ハラル") to get the English PDF.
function getSurrounding(html, idx, before, after) {
  var s = Math.max(0, idx - before);
  var e = Math.min(html.length, idx + after);
  return html.substring(s, e);
}

// Halal: prefer English keyword ("Halal"), fall back to Japanese ("ハラル")
var halalLink = null;
for (var pass = 0; pass < 2 && !halalLink; pass++) {
  var keyword = pass === 0 ? 'Halal' : 'ハラル';
  for (var i = 0; i < links.length && !halalLink; i++) {
    var ctx = getSurrounding(htmlBody, links[i].index, 200, 100);
    if (ctx.indexOf(keyword) !== -1) {
      halalLink = links[i];
    }
  }
}

if (!halalLink) {
  throw new Error('No Halal menu link found in email.');
}

return [
  { pdfUrl: halalLink.url, campus: 'Uzumasa' },
];

const base64Pdf = $input.all()[0].json.base64Pdf;
if (!base64Pdf) throw new Error('No PDF returned from fetcher VM');
const campus = 'Uzumasa';
const now = new Date();
const weekOf = now.toISOString().slice(0, 10);
return { base64Pdf, campus, weekOf };

