const responseData = $input.all()[0].json;

const parts = responseData.candidates?.[0]?.content?.parts;
if (!parts || !parts[0]) {
  throw new Error(
    'No content in Gemini response. finishReason=' +
    responseData.candidates?.[0]?.finishReason +
    ' promptFeedback=' + JSON.stringify(responseData.promptFeedback) +
    ' error=' + JSON.stringify(responseData.error)
  );
}
const rawText = parts[0].text;
if (!rawText) throw new Error('No text in Gemini response');

const campus = 'Uzumasa';
const weekOf = new Date().toISOString().slice(0, 10);

let dishes;
try {
  dishes = JSON.parse(rawText);
} catch(e) {
  const match = rawText.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (match) {
    dishes = JSON.parse(match[1].trim());
  } else {
    throw new Error('Parse failed: ' + e.message + '\\nRaw: ' + rawText.slice(0, 200));
  }
}
if (!Array.isArray(dishes)) throw new Error('Not an array');

return dishes
  .filter(d => d.dish_name && d.dish_name.trim() !== '')
  .map(d => ({
    campus,
    week_of: weekOf,
    day_name: d.day_name || null,
    menu_date: d.menu_date ? d.menu_date.slice(0, 10) : null,
    category: d.category || null,
    subcategory: d.subcategory || null,
    dish_name: d.dish_name,
    allergens: d.allergens || null,
    calories: d.calories || null,
    protein: d.protein || null,
    fat: d.fat || null,
    sodium: d.sodium || null,
  }));

