// Pack every parsed row into one base64 blob for a single INSERT ... ON CONFLICT.
// Postgres raises a unique violation for *any* duplicate key in a multi-row
// INSERT, and the Halal poster repeats a whole month every run, so one row that
// already exists used to abort the entire batch and nothing new was ever stored.
const rows = $input
  .all()
  .map((item) => item.json)
  .filter((r) => r.dish_name && r.menu_date);

return [{ json: { rows_b64: Buffer.from(JSON.stringify(rows), 'utf8').toString('base64'), rows: rows.length } }];
